import * as React from "react"

import { cn } from "@/lib/utils"

type MarkerProps = React.ComponentProps<"p"> & {
  /** A divider draws its rules outward from the word: where a day begins. */
  variant?: "status" | "divider"
  /** A small dot before a status. */
  dot?: boolean
  /** Plays the arrival when it mounts (the rules push apart). */
  arriving?: boolean
}

/** A quiet line in a conversation: a status, or where a day begins. */
function Marker({ variant = "status", dot, arriving, className, children, ...props }: MarkerProps) {
  return (
    <p
      data-slot="marker"
      data-variant={variant === "divider" ? "divider" : undefined}
      data-arriving={arriving || undefined}
      className={cn("db-marker", className)}
      {...props}
    >
      {dot ? <span className="db-marker-dot" aria-hidden="true" /> : null}
      {children}
    </p>
  )
}

export { Marker, type MarkerProps }

@layer components {
  /* ── db-marker ── a quiet line in a conversation: a status, or a day */
  .db-marker { display: flex; align-items: center; gap: var(--db-space-3); font-size: var(--db-pp); line-height: var(--db-pp-lh); color: var(--db-pencil); }
  .db-marker-dot { width: 5px; height: 5px; border-radius: 50%; background: currentColor; }
  .db-marker[data-variant="divider"] { gap: var(--db-space-4); color: var(--db-graphite); }
  .db-marker[data-variant="divider"]::before, .db-marker[data-variant="divider"]::after { content: ""; flex: 1; height: var(--db-hairline); background: var(--db-rule-strong); }
  .db-marker[data-variant="divider"]::before { transform-origin: 100% 50%; }
  .db-marker[data-variant="divider"]::after { transform-origin: 0 50%; }
  .db-marker[data-arriving]::before, .db-marker[data-arriving]::after { animation: db-draw-x var(--db-andante) var(--db-exhale) backwards; }
  .db-marker[data-arriving] { animation: db-arrive var(--db-moderato) var(--db-exhale) backwards; }
}
